// S016 Gate 2 independent checker (Node), written separately from s016_clear_layers.rs.
// Same mathematical recursion (research/S016_CLEAR.md C4-C6), different organisation:
// configurations are strings of UTF-16 code units (one per vertex); the 0/1 base layer
// is generated by recursive combinations; predecessors are generated from each loser by
// choosing an occupied receiver v and then a neighbour u of v; non-bipartiteness is
// decided by connectivity of the bipartite double cover.
// usage: node s016_clear_check.mjs MODE LO HI SECONDS LAYERCAP < graphs > out
//   prints, for graph lines with index in [LO,HI):  name status Lall LAS crit critAS | crit-list
import { readFileSync } from 'node:fs';
const [mode, lo, hi, secs, cap] = [process.argv[2], +process.argv[3], +process.argv[4], +process.argv[5], +process.argv[6]];
if (mode !== 'clear' && mode !== 'stack') throw new Error('mode');
const lines = readFileSync(0, 'utf8').split(/\r?\n/).filter(s => s.trim());

function doubleCoverConnected(n, nb) {
  // vertices (v,side) -> 2v+side ; edge uv joins (u,0)-(v,1) and (u,1)-(v,0)
  const seen = new Uint8Array(2 * n); const st = [0]; seen[0] = 1; let cnt = 1;
  while (st.length) {
    const x = st.pop(); const v = x >> 1, side = x & 1;
    for (const u of nb[v]) { const y = 2 * u + (1 - side); if (!seen[y]) { seen[y] = 1; cnt++; st.push(y); } }
  }
  return cnt === 2 * n;
}
function connected(n, nb) {
  const seen = new Uint8Array(n); const st = [0]; seen[0] = 1; let cnt = 1;
  while (st.length) { const v = st.pop(); for (const u of nb[v]) if (!seen[u]) { seen[u] = 1; cnt++; st.push(u); } }
  return cnt === n;
}
const enc = a => String.fromCharCode(...a);
const decArr = s => Array.from(s, ch => ch.charCodeAt(0));
const heavyCount = a => a.reduce((h, x) => h + (x > 1 ? 1 : 0), 0);

function solve(n, nb) {
  const t0 = Date.now();
  let prev = new Set(); let LAS = 0;
  for (let t = 2; ; t++) {
    const cand = new Set();
    if (t <= n) {
      const a = new Array(n).fill(0);
      const rec = (i, left) => {
        if (left === 0) { cand.add(enc(a)); return; }
        if (n - i < left) return;
        a[i] = 1; rec(i + 1, left - 1); a[i] = 0; rec(i + 1, left);
      };
      rec(0, t);
    }
    for (const s of prev) {
      const a = decArr(s);
      for (let v = 0; v < n; v++) if (a[v] >= 1) for (const u of nb[v]) {
        a[v] -= 1; a[u] += 2;
        if (a[u] > 50000) return { status: 'OVERFLOW_UNKNOWN' };
        cand.add(enc(a)); a[v] += 1; a[u] -= 2;
      }
    }
    const cur = new Set();
    for (const c of cand) {
      const a = decArr(c);
      if (mode === 'stack' && a.filter(x => x > 0).length === 1) continue;
      let lose = true;
      outer: for (let u = 0; u < n; u++) if (a[u] >= 2) for (const v of nb[u]) {
        a[u] -= 2; a[v] += 1; const k = enc(a); a[u] += 2; a[v] -= 1;
        if (!prev.has(k)) { lose = false; break outer; }
      }
      if (lose) cur.add(c);
    }
    if (cur.size === 0) {
      const crit = [...prev].map(decArr);
      return { status: LAS === t - 1 ? 'ASH_OK' : 'ASH_FAIL', Lall: t - 1, LAS, crit };
    }
    for (const c of cur) if (heavyCount(decArr(c)) <= 1) { LAS = t; break; }
    if (cur.size > cap || (Date.now() - t0) / 1000 > secs) return { status: 'CAP_UNKNOWN' };
    prev = cur;
  }
}

for (let i = lo; i < Math.min(hi, lines.length); i++) {
  const f = lines[i].trim().split(/\s+/); const name = f[0], n = +f[1];
  const nb = Array.from({ length: n }, () => []);
  if (f[2]) for (const e of f[2].split(',')) { const [x, y] = e.split('-').map(Number); nb[x].push(y); nb[y].push(x); }
  if (!connected(n, nb)) { console.log(`${name} DISCONNECTED_SKIP`); continue; }
  if (mode === 'clear' && !doubleCoverConnected(n, nb)) { console.log(`${name} BIPARTITE_SKIP`); continue; }
  const r = solve(n, nb);
  if (!r.crit) { console.log(`${name} ${r.status}`); continue; }
  const cas = r.crit.filter(a => heavyCount(a) <= 1).length;
  const list = r.crit.map(a => a.join('.')).sort().join(' ');
  console.log(`${name} ${r.status} ${r.Lall} ${r.LAS} ${r.crit.length} ${cas} | ${list}`);
}
